mapper.select:
SELECT ${params.column},d.QUESTION_DSCR as P_QUESTION_DSCR,a.APPROVAL_STATE, a.SORT, a.PATH AS path FROM inspection.inspection_question_bank a LEFT JOIN inspection.inspection_question_bank d on a.QUESTION_PID = d.QUESTION_ID LEFT JOIN inspection.inspection_question_rule_relation b on a.QUESTION_ID = b.QUESTION_ID LEFT JOIN inspection.inspection_question_rule c on b.RULE_ID = c.RULE_ID LEFT JOIN (SELECT a.QUESTION_ID, group_concat(e.ENUM_DSCR) as QUESTION_TYPE_DSCR, group_concat(e.ENUM_ID) as QUESTION_TYPE FROM inspection.inspection_question_bank_type a, enumset.cm_guoku_enumeration e WHERE e.ENUM_TYPE_ID IN(12, 21) AND a.TYPE = e.ENUM_ID
AND a.TYPE = #{params.QUESTION_TYPE}
group by a.QUESTION_ID )z on a.QUESTION_ID = z.QUESTION_ID WHERE 1 = 1 and (a.QUESTION_PID is NULL or a.QUESTION_PID = '')
AND a.QUESTION_ID = #{params.QUESTION_ID}
AND a.QUESTION_DSCR like '%${params.key_word}%' or a.QUESTION_DETAILS LIKE '%${params.key_word}%'
AND a.isleaf = #{params.isleaf}
AND c.RULE_FILE_CONTENT like '%${params.RULE_FILE_CONTENT}%'
AND a.APPROVAL_STATE = #{params.APPROVAL_STATE}
order by a.SORT

SELECT DISTINCT ${params.column},d.QUESTION_DSCR as P_QUESTION_DSCR,a.APPROVAL_STATE, a.PATH AS path FROM inspection.inspection_question_bank a JOIN inspection.inspection_question_bank d on a.QUESTION_PID = d.QUESTION_ID left JOIN inspection.inspection_question_rule_relation b on a.QUESTION_ID = b.QUESTION_ID left join inspection.inspection_question_rule c on b.RULE_ID = c.RULE_ID LEFT JOIN (SELECT a.QUESTION_ID, group_concat(e.ENUM_DSCR) as QUESTION_TYPE_DSCR, group_concat(e.ENUM_ID) as QUESTION_TYPE FROM inspection.inspection_question_bank_type a, enumset.cm_guoku_enumeration e WHERE e.ENUM_TYPE_ID IN(12, 21) AND a.TYPE = e.ENUM_ID
AND a.TYPE = #{params.QUESTION_TYPE}
group by a.QUESTION_ID )z on a.QUESTION_ID = z.QUESTION_ID WHERE 1 = 1
AND a.QUESTION_ID = #{params.QUESTION_ID}
AND a.QUESTION_PID = #{params.QUESTION_PID}
AND a.QUESTION_DSCR like '%${params.key_word}%' or a.QUESTION_DETAILS LIKE '%${params.key_word}%'
AND a.isleaf = #{params.isleaf}
AND (a.QUESTION_TYPE = #{params.QUESTION_TYPE} or a.QUESTION_TYPE = '' or a.QUESTION_TYPE is NULL)
AND c.RULE_FILE_CONTENT like '%${params.RULE_FILE_CONTENT}%'
AND a.QUESTION_PID = #{params.parentId}
AND a.APPROVAL_STATE = #{params.APPROVAL_STATE}
order by a.SORT

SELECT count(1) FROM inspection.inspection_question_bank a left JOIN inspection.inspection_question_rule_relation b on a.QUESTION_ID = b.QUESTION_ID left join inspection.inspection_question_rule c on b.RULE_ID = c.RULE_ID LEFT JOIN (SELECT a.QUESTION_ID, group_concat(e.ENUM_DSCR) as QUESTION_TYPE_DSCR, group_concat(e.ENUM_ID) as QUESTION_TYPE FROM inspection.inspection_question_bank_type a, enumset.cm_guoku_enumeration e WHERE e.ENUM_TYPE_ID IN(12, 21) AND a.TYPE = e.ENUM_ID
AND a.TYPE = #{params.QUESTION_TYPE}
group by a.QUESTION_ID )z on a.QUESTION_ID = z.QUESTION_ID WHERE 1 = 1 and (a.QUESTION_PID is NULL or a.QUESTION_PID = '')
AND a.QUESTION_ID = #{params.QUESTION_ID}
AND a.QUESTION_DSCR like '%${params.key_word}%' or a.QUESTION_DETAILS LIKE '%${params.key_word}%'
AND a.isleaf = #{params.isleaf}
AND (a.QUESTION_TYPE = #{params.QUESTION_TYPE} or a.QUESTION_TYPE = '' or a.QUESTION_TYPE is NULL)
AND c.RULE_FILE_CONTENT like '%${params.RULE_FILE_CONTENT}%'

