mapper.select:
SELECT * FROM inspection.inspection_question_bank a WHERE 1 = 1
AND a.QUESTION_ID != #{params.QUESTION_ID}
AND a.QUESTION_DSCR = #{params.QUESTION_DSCR}

SELECT QUESTION_ID as id, QUESTION_DSCR as name, ifnull(QUESTION_PID,'') as pid, isleaf, ifnull(sort,'') AS sort FROM inspection.inspection_question_bank a WHERE 1 = 1
AND a.QUESTION_ID = #{params.QUESTION_ID}
AND a.QUESTION_DSCR = #{params.QUESTION_DSCR}
AND a.QUESTION_PID = #{params.QUESTION_PID}
AND a.QUESTION_TYPE = #{params.QUESTION_TYPE}
order by SORT
